import{_ as e,o as n,c as o,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Statement Download Agent","description":"","frontmatter":{"title":"Statement Download Agent"},"headers":[],"relativePath":"docs/tools/statement-agents.md","filePath":"docs/tools/statement-agents.md","lastUpdated":1793819983000}'),s={name:"docs/tools/statement-agents.md"};function r(i,t,d,l,h,m){return n(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="statement-download-agent-beta" tabindex="-1">Statement Download Agent (Beta) <a class="header-anchor" href="#statement-download-agent-beta" aria-label="Permalink to &quot;Statement Download Agent (Beta)&quot;">​</a></h1><p>The supported way to bring statements into OrbySystems is to download them from your bank&#39;s website and add the files. The <strong>Statement Download Agent</strong> is the quicker way, at the banks it knows, and it never takes over: you sign in and open your statements page in the OrbySystems browser, and it downloads all your statements, or only the new ones, and adds them to your project.</p><p>You stay in control of your accounts. Agents never store or type a password, never download on their own, and never act on your accounts: they only read the statements page you opened.</p><p>Each bank has its own agent. Open it from a project&#39;s <strong>+ Add</strong>: choose <strong>have the Statement Download Agent (Beta) download them for you</strong>, and type your bank&#39;s name. The tool itself, under <strong>Tools</strong>, has two tabs: <strong>Supported institutions</strong> and <strong>Add a new institution</strong>.</p><h2 id="getting-statements" tabindex="-1">Getting statements <a class="header-anchor" href="#getting-statements" aria-label="Permalink to &quot;Getting statements&quot;">​</a></h2><ol><li>Type your bank&#39;s name and choose it. OrbySystems opens its website in the OrbySystems browser.</li><li>Sign in yourself, and go to your statements page.</li><li>Come back to OrbySystems and choose <strong>I&#39;m already at the statements page</strong>, or <strong>Take me to the statements page</strong> to let the agent open it. The agent lists what it finds and compares it with the project; nothing is downloaded yet.</li><li>The accounts with statements the project doesn&#39;t have yet are ticked: months after its latest for that account, and not already in the account&#39;s download folder. Months the project probably has are left out; choose <strong>download them too</strong> on an account to include them, for instance to fill in older months. Choose <strong>Download</strong>: the statements are saved in a folder per account and added to the project.</li></ol><p>The first run of a newly delivered agent is its trial run, so you can see it work before relying on it. Only one agent runs at a time, since they share one browser.</p><h2 id="add-a-new-institution" tabindex="-1">Add a new institution <a class="header-anchor" href="#add-a-new-institution" aria-label="Permalink to &quot;Add a new institution&quot;">​</a></h2><p>If your bank has no agent yet, OrbySystems makes one. Show it the way to one statement:</p><ol><li>Launch the OrbySystems browser and open your bank&#39;s site.</li><li>Sign in, and go to your statements page.</li><li>Press <strong>Record</strong>, download one statement in the browser, then come back and press <strong>Stop and save</strong>.</li></ol><p>OrbySystems notes only what you click, never anything you type, and keeps the recording on your computer. You read a copy of it with your names and numbers faked, and send it to OrbySystems once you&#39;ve confirmed nothing of yours is in it. Nothing leaves your computer until you send it. The agent OrbySystems makes is tried on your statements page before it&#39;s installed, and the institution then appears under <strong>Supported institutions</strong>.</p>',11)])])}const y=e(s,[["render",r]]);export{u as __pageData,y as default};
